begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','agency@example.invalid',now()),('33333333-3333-4333-8333-333333333333','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
insert into fixture values('agency',public.create_agency('Agency',gen_random_uuid()));
select throws_ok($$select public.create_brand_claim_request((select id from fixture where key='agency'),'Client','owner@example.invalid','','UTC',gen_random_uuid(),false)$$,'22023',null,'Agency must attest authority to initiate setup');
insert into fixture values('claim',public.create_brand_claim_request((select id from fixture where key='agency'),'Client','owner@example.invalid','https://example.invalid','UTC','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
select is(public.create_brand_claim_request((select id from fixture where key='agency'),'Client','owner@example.invalid','https://example.invalid','UTC','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true),(select id from fixture where key='claim'),'Claim request retry is idempotent');
select is((select state from public.brand_claim_requests),'unclaimed','Agency setup starts explicitly unclaimed');
select is((select count(*)::int from public.brand_workspaces),0,'Agency request creates no owner workspace or powers');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='claim'),'Agency',true)$$,'42501',null,'Agency cannot claim on behalf of named owner');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_claim_requests),0,'Unrelated verified account cannot inspect claim');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='claim'),'Other',true)$$,'42501',null,'Wrong recipient cannot claim');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_claim_requests),1,'Named verified recipient sees claim');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='claim'),'Owner',false)$$,'22023',null,'Owner must independently attest ownership');
insert into fixture values('brand',public.accept_brand_claim_request((select id from fixture where key='claim'),'Owner organization',true));
select ok(public.current_brand_capability((select id from fixture where key='brand'),'workspace.manage'),'Claimed workspace belongs to verified recipient');
select is((select created_by from public.brand_workspaces),'11111111-1111-4111-8111-111111111111'::uuid,'Actual owner creates workspace');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='claim'),'Other organization',true)$$,'22023',null,'Accepted claim cannot create another workspace');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_workspaces),0,'Agency does not silently retain access after claim');
insert into fixture values('dispute',public.create_brand_claim_request((select id from fixture where key='agency'),'Disputed client','owner@example.invalid','','UTC',gen_random_uuid(),true));
insert into fixture values('expired',public.create_brand_claim_request((select id from fixture where key='agency'),'Expired client','owner@example.invalid','','UTC',gen_random_uuid(),true));
reset role;
update public.brand_claim_requests set expires_at=now()-interval '1 minute' where id=(select id from fixture where key='expired');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.close_brand_claim_request((select id from fixture where key='dispute'),'disputed','Not authorized by our organization');
select is((select decision_reason from public.brand_claim_requests where id=(select id from fixture where key='dispute')),'Not authorized by our organization','Dispute context remains visible');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='dispute'),'Owner',true)$$,'22023',null,'Disputed claim cannot transfer or create ownership');
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='expired'),'Owner',true)$$,'22023',null,'Expired claim cannot establish ownership');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
insert into fixture values('revoked',public.create_brand_claim_request((select id from fixture where key='agency'),'Revoked creator','owner@example.invalid','','UTC',gen_random_uuid(),true));
reset role;
update public.organization_memberships set active=false where organization_id=(select id from fixture where key='agency');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$select public.accept_brand_claim_request((select id from fixture where key='revoked'),'Owner',true)$$,'42501',null,'Revoked initiating administrator invalidates pending claim');
select is((select count(*)::int from public.brand_workspaces),1,'Rejected claims do not create additional workspaces');
reset role;
select * from finish();
rollback;
